import AppKit
import QaliDomain
import SwiftUI

/// The web design tokens as asset-catalog colours (light + dark), generated by
/// scripts/gen-colors.py from packages/ui/src/styles/globals.css. Names follow
/// the web vocabulary: `primary` is the brand black/white, `mutedForeground`
/// the muted text colour.
enum Palette {
  static let background = Color("background")
  static let foreground = Color("foreground")
  static let card = Color("card")
  static let cardForeground = Color("cardForeground")
  static let popover = Color("popover")
  static let primary = Color("primary")
  static let primaryForeground = Color("primaryForeground")
  static let secondary = Color("secondary")
  static let muted = Color("muted")
  static let mutedForeground = Color("mutedForeground")
  static let accent = Color("accent")
  static let calendarHeader = Color("calendarHeader")
  static let destructive = Color("destructive")
  static let border = Color("border")
  static let input = Color("input")
  static let ring = Color("ring")
  static let link = Color("link")
  static let eventNeutral = Color("eventNeutral")

  /// `--event-1` … `--event-8`.
  static func event(_ index: Int) -> Color { Color("event\(index)") }

  /// The colour for a palette key picked by QaliDomain (an event's or a
  /// calendar's snapped hue, or the neutral).
  static func event(_ key: EventPaletteKey) -> Color {
    key.hueIndex.map(event) ?? eventNeutral
  }

  /// `--chroma-1` … `--chroma-5`, the band that sweeps across the loader.
  static func chroma(_ index: Int) -> Color { Color("chroma\(index)") }

  /// The same tokens for AppKit surfaces (the window behind the SwiftUI
  /// content), resolved against the view's appearance like any named colour.
  enum AppKit {
    static let background = NSColor(named: "background") ?? .windowBackgroundColor
  }
}
